async function load(charactersOnly=false){if(!db)return;if(charactersOnly){const {data,error}=await db.from('characters').select('*').order('name');if(error){notice(error.message);return}setChars((data as Character[]).map(normalizeCharacter));await Promise.all([loadEffects(),loadScrolls()]);return}const results=await Promise.all([db.from('characters').select('*').order('name'),db.from('rules').select('*').order('title'),db.from('mechanics_config').select('*').eq('id','campaign').single(),db.from('profiles').select('id,display_name,role').order('display_name')]);if(results.some(r=>r.error)){notice(results.find(r=>r.error)?.error?.message||'加载失败');return}setChars((results[0].data as Character[]).map(normalizeCharacter));setRules(results[1].data as Rule[]);setProfiles(results[3].data as Account[]);if(results[2].data&&validateMechanics(results[2].data.config))setMechanics(upgradeMechanicsRecord(results[2].data as MechanicsRecord));else notice('计算配置无效，请联系 DM');await Promise.all([loadEffects(),loadScrolls()])}
