async function changeScrollStock(items:Record<string,number>,version:number){if(!gm)return;setBusy(true);try{const next={items,version:version+1};validateScrolls(next);if(db){const {data,error}=await db.from('shared_scrolls').update({items,version:next.version}).eq('id',1).eq('version',version).select().single();if(error||!data)throw Error('卷轴库存已变化或保存失败，请刷新');setScrolls({items:data.items,version:data.version})}else await navigator.locks.request('viola-scrolls',()=>{const latest=cached('viola-scrolls',emptyScrolls());if(latest.version!==version){setScrolls(latest);throw Error('卷轴库存已变化，请重试')}for(const [id,n]of Object.entries(items))if(n>0&&n!==(latest.items[id]??0)&&!scrollProfile(mechanics.config.modules?.[id]))throw Error('只能添加有效的普通法术卷轴');localStorage.setItem('viola-scrolls',JSON.stringify(next));setScrolls(next)});notice('卷轴库存已保存')}catch(e){notice((e as Error).message)}finally{setBusy(false)}}
async function useScroll(c:Character,choice:ScrollChoice,version:number){setBusy(true);try{if(!canControlCharacter(c,chars,user,gm)||c.master_id)throw Error('请选择自己控制的玩家角色');if(db){const {data,error}=await db.functions.invoke('module-state',{body:{operation:'scroll_cast',characterId:c.id,version:c.version,inventoryVersion:version,choice}});if(error||!data?.character)throw Error(data?.error||error?.message||'卷轴施放失败');setChars(old=>old.map(row=>row.id===c.id?data.character:row));await loadScrolls();await loadEffects()}else await navigator.locks.request('viola-scrolls',()=>{const inventory=cached('viola-scrolls',emptyScrolls()),latestChars=cached<Character[]>('ember-characters',chars),latest=latestChars.find(row=>row.id===c.id);if(inventory.version!==version){setScrolls(inventory);throw Error('卷轴库存已变化，请重试')}if(!latest||latest.version!==c.version)throw Error('角色已变化，请刷新后重试');if((inventory.items[choice.moduleId]??0)<1)throw Error('卷轴已用完');const effects=buildEffectContext(latestChars,mechanics.config),result=performScrollCast(latest,mechanics.config,choice,gm,effects.roster),profile=scrollProfile(mechanics.config.modules?.[choice.moduleId])!,entry={id:crypto.randomUUID(),time:new Date().toISOString(),text:`使用公共卷轴：${mechanics.config.modules![choice.moduleId].name} · ${profile.ring}环／CL${profile.casterLevel} · 消耗1张${choice.targets?.length?' · 目标：'+choice.targets.map(id=>effects.roster.find(p=>p.id===id)?.name??id).join('、'):''}`},updated={...latest,...result,version:latest.version+1,rule_state:{...result.rule_state,auditLog:[...(latest.rule_state?.auditLog??[]),entry]}},next={version:inventory.version+1,items:{...inventory.items,[choice.moduleId]:inventory.items[choice.moduleId]-1}},newChars=latestChars.map(row=>row.id===c.id?updated:row),beforeInventory=localStorage.getItem('viola-scrolls'),beforeChars=localStorage.getItem('ember-characters');try{localStorage.setItem('viola-scrolls',JSON.stringify(next));localStorage.setItem('ember-characters',JSON.stringify(newChars))}catch(e){if(beforeInventory===null)localStorage.removeItem('viola-scrolls');else localStorage.setItem('viola-scrolls',beforeInventory);if(beforeChars!==null)localStorage.setItem('ember-characters',beforeChars);throw e}setScrolls(next);setChars(newChars)});notice('已消耗一张卷轴并施放；即时效果按描述结算')}catch(e){notice((e as Error).message)}finally{setBusy(false)}}
async function saveMechanics(config:Mechanics,version:number){if(!gm||!validateMechanics(config))return;setBusy(true);try{if(db){const {data,error}=await db.from('mechanics_config').update({config,version:version+1}).eq('id','campaign').eq('version',version).select().single();if(error||!data){await load();throw new Error('配置保存失败或版本已更新，请检查后重试：'+(error?.message||''))}setMechanics(data as MechanicsRecord)}else{if(mechanics.version!==version)throw new Error('配置版本已更新');setMechanics({id:'campaign',config,version:version+1})}notice('计算配置已保存，角色结果已更新')}catch(e){notice((e as Error).message)}finally{setBusy(false)}}
