function backup(){const blob=new Blob([JSON.stringify({format:'ember-v1',exported_at:new Date().toISOString(),characters:visible,rules,mechanics,scrolls,accounts:accounts.filter(a=>gm||a.id===user)},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`ember-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);notice('已导出可见数据；完整数据库备份请使用 Supabase CLI')}
