function CharacterCard({c,gm,busy,save,mechanics}:{c:Character;gm:boolean;busy:boolean;save:(c:Character,p:Partial<Character>)=>Promise<void>;mechanics:MechanicsRecord}){
 const[d,setD]=useState(c);const availableClasses=classCatalog(mechanics.config);
 const[nextClass,setNextClass]=useState<string>(availableClasses[0].id),[endLevel,setEndLevel]=useState(c.class_levels.length+1);
 const can=(key:string)=>gm||c.editable_fields.includes(key);
 const editable=['name','race','class_levels',...abilityFields.map(([key])=>key)];const permissionFields=[...editable,'ability_permanent','ability_temporary','hp_long_effects','hp_short_effects','derived_long_effects','derived_short_effects','weapon_context','hp','resources'];
 const permissions:Record<string,string>={name:'姓名',race:'种族',class_levels:'职业逐级分配',...Object.fromEntries(abilityFields.map(([k,v])=>[k,v+'·天生'])),ability_permanent:'六大属性长效来源',ability_temporary:'六大属性短效来源',hp_long_effects:'HP 长效明细',hp_short_effects:'HP 短效明细',derived_long_effects:'命中、豁免、技能点长效来源',derived_short_effects:'命中、豁免短效来源',hp:'当前生命（手动修改）',resources:'原有角色资源（当前值）',weapon_context:'武器变量（还需变量声明允许 PL）'};
 const ranges=levelRanges(d.class_levels);
 function appendLevels(){if(!Number.isInteger(endLevel)||endLevel<=d.class_levels.length||endLevel>100)return;setD({...d,class_levels:[...d.class_levels,...Array(endLevel-d.class_levels.length).fill(nextClass)]});setEndLevel(endLevel+1)}
 const actualAbilities=calculateAbilities(prepareModules(d,mechanics.config).character);const valid=abilityFields.every(([key])=>Number.isInteger(d[key])&&d[key]>=0&&actualAbilities[key]>=0);
 return <form className="panel sheet" onSubmit={e=>{e.preventDefault();if(!valid)return;const patch=Object.fromEntries(editable.filter(can).map(k=>[k,d[k as keyof Character]]));void save(c,gm?{...patch,editable_fields:d.editable_fields}:patch)}}>
 <span className="eyebrow">CHARACTER RECORD · 总等级 {d.class_levels.length}</span><h2>{d.name}</h2>
 <div className="identity-fields"><label>姓名 {!can('name')&&'🔒'}<input required maxLength={100} disabled={!can('name')} value={d.name} onChange={e=>setD({...d,name:e.target.value})}/></label><label>种族 {!can('race')&&'🔒'}<select disabled={!can('race')} value={d.race} onChange={e=>setD({...d,race:e.target.value})}><option value="">请选择种族</option>{d.race&&!Object.hasOwn(mechanics.config.races,d.race)&&<option value={d.race} disabled>旧记录：{d.race}（请重选）</option>}{Object.keys(mechanics.config.races).map(r=><option key={r} value={r}>{r}</option>)}</select></label></div>
 <section className="basics"><h3>职业与升级顺序 {!can('class_levels')&&'🔒'}</h3><p className="class-summary">{classSummary(d.class_levels,availableClasses)}</p><div className="level-ranges">{ranges.map(r=><span className="badge" key={r.start}>{r.start===r.end?`第 ${r.start} 级`:`${r.start}–${r.end} 级`} · {availableClasses.find(x=>x.id===r.classId)?.name}</span>)}</div>
 {d.class_levels.length===0&&<p className="muted">尚未分配职业等级。旧职业文字保留在导出数据中，不会自动猜测转换。</p>}
 {can('class_levels')&&d.class_levels.length<100&&<div className="level-add"><label>从第 {d.class_levels.length+1} 级起选择职业<select value={nextClass} onChange={e=>setNextClass(e.target.value)}>{availableClasses.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label>到第几级<input type="number" min={d.class_levels.length+1} max={100} step={1} value={endLevel} onChange={e=>setEndLevel(Number(e.target.value))}/></label><button type="button" disabled={busy||!Number.isInteger(endLevel)||endLevel<=d.class_levels.length||endLevel>100} onClick={appendLevels}>添加等级段</button></div>}
 {d.class_levels.length>0&&<details><summary>查看／修改每一级职业</summary><div className="level-grid">{d.class_levels.map((id,index)=><label key={index}>第 {index+1} 级<select disabled={!can('class_levels')} value={id} onChange={e=>setD({...d,class_levels:d.class_levels.map((x,i)=>i===index?e.target.value:x)})}>{availableClasses.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label>)}</div>{can('class_levels')&&<button className="secondary" type="button" onClick={()=>{setD({...d,class_levels:d.class_levels.slice(0,-1)});setEndLevel(d.class_levels.length)}}>移除最后一级</button>}</details>}
 <p className="muted">数值结果请查看“当前状态”。</p></section>
 <section className="basics"><h3>六大属性 · 天生</h3><div className="ability-grid">{abilityFields.map(([key,label])=><label key={key}>{label} {!can(key)&&'🔒'}<input aria-label={label+'天生'} type="number" min={0} step={1} required disabled={!can(key)} value={d[key]} onChange={e=>setD({...d,[key]:Number(e.target.value)})}/></label>)}</div>{!valid&&<p role="alert">天生属性需为非负整数，已有调整后的总值不能低于 0。</p>}</section>
 {gm&&<details><summary>GM 权限设置</summary><p>勾选允许玩家编辑；不勾选即锁定。天生属性默认由 GM 控制。</p>{permissionFields.map(k=><label className="check" key={k}><input type="checkbox" checked={d.editable_fields.includes(k)} onChange={e=>setD({...d,editable_fields:e.target.checked?[...d.editable_fields,k]:d.editable_fields.filter(x=>x!==k)})}/>{permissions[k]}</label>)}</details>}
 <div className="save-row"><small className="muted">版本 {c.version} · 手动保存后同步</small><button disabled={busy||!valid}>{busy?'保存中…':'保存角色 →'}</button></div></form>
}
function AccountAssignments({accounts,chars,busy,local,onAssign,onAdd,onDeleteAccount,onRefresh}:{accounts:Account[];chars:Character[];busy:boolean;local:boolean;onAssign:(accountId:string,characterId:string)=>Promise<void>;onAdd:(id:string)=>void;onDeleteAccount:(id:string)=>void;onRefresh:()=>void}){
 const[newId,setNewId]=useState(''),[pendingAccount,setPendingAccount]=useState<string|null>(null);
 return <section className="panel management"><div className="section-title"><h2>账号 → 对应角色</h2>{!local&&<button className="secondary" disabled={busy} onClick={onRefresh}>刷新账号</button>}</div><div className="management-scroll"><table><thead><tr><th>账号</th><th>对应角色</th>{local&&<th>操作</th>}</tr></thead><tbody>{accounts.map(a=>{const owned=chars.filter(c=>c.owner_id===a.id);return <tr key={a.id}><td>{a.display_name||a.id}<small>{a.id}</small></td><td>{a.role==='gm'?<span>GM · 全部角色</span>:<><select aria-label={`${a.display_name||a.id}对应角色`} disabled={busy} value={owned.length===1?owned[0].id:''} onChange={e=>void onAssign(a.id,e.target.value)}><option value="">{owned.length>1?'当前有多个角色，请重新选择':'未分配'}</option>{chars.filter(c=>!c.master_id).map(c=><option key={c.id} value={c.id}>{c.name}{c.owner_id&&c.owner_id!==a.id?'（已分配给其他账号）':''}</option>)}</select>{owned.length>1&&<small>当前：{owned.map(c=>c.name).join('、')}</small>}</>}</td>{local&&<td>{a.role!=='gm'&&(pendingAccount===a.id?<div className="delete-confirm"><span>删除账号“{a.display_name||a.id}”？角色仅解绑，仍会保留。</span><button className="danger" disabled={busy} onClick={()=>{onDeleteAccount(a.id);setPendingAccount(null)}}>确认删除账号</button><button className="secondary" disabled={busy} onClick={()=>setPendingAccount(null)}>取消</button></div>:<button className="secondary danger-text" disabled={busy} onClick={()=>setPendingAccount(a.id)}>删除账号</button>)}</td>}</tr>})}</tbody></table></div><p className="muted">下拉选择后立即保存。选择其他账号的角色会将其转交；选择“未分配”则解除关联。</p>{local&&<form onSubmit={e=>{e.preventDefault();onAdd(newId);setNewId('')}}><label>新增本机测试账号<input value={newId} maxLength={100} required placeholder="例如 player03" onChange={e=>setNewId(e.target.value)}/></label><button className="secondary" disabled={busy}>添加测试账号</button></form>}</section>
}
function CharacterManagement({chars,busy,onDelete,onMaster}:{chars:Character[];busy:boolean;onDelete:(c:Character)=>Promise<void>;onMaster:(c:Character,id:string)=>Promise<void>}){
 const[pending,setPending]=useState<string|null>(null);
 return <section className="panel management"><h2>角色管理与从属关联</h2><p className="muted">先创建从属角色卡，再选择它的主人；关联后由主人账号控制。解除关联后保持未分配，删除主人会保留从属卡并解绑。</p><div className="management-scroll"><table><thead><tr><th>角色</th><th>主人角色</th><th>操作</th></tr></thead><tbody>{chars.map(c=><tr key={c.id}><td>{c.name}</td><td><select aria-label={`${c.name}的主人角色`} disabled={busy} value={c.master_id||''} onChange={e=>void onMaster(c,e.target.value)}><option value="">独立角色</option>{chars.filter(x=>x.id!==c.id&&!x.master_id).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></td><td>{pending===c.id?<div className="delete-confirm"><span>确认删除“{c.name}”？删除后无法在网页恢复。</span><button className="danger" disabled={busy} onClick={()=>{void onDelete(c);setPending(null)}}>确认删除</button><button className="secondary" disabled={busy} onClick={()=>setPending(null)}>取消</button></div>:<button className="secondary danger-text" disabled={busy} onClick={()=>setPending(c.id)}>删除角色</button>}</td></tr>)}</tbody></table></div>{!chars.length&&<p className="muted">暂无角色。</p>}</section>
}
function QuickCard({c,gm,busy,save,mechanics,incoming=[],roster=[]}:{incoming?:SharedEffect[];roster?:CharacterPeer[];c:Character;gm:boolean;busy:boolean;save:(c:Character,p:Partial<Character>)=>Promise<void>;mechanics:MechanicsRecord}){
 const[d,setD]=useState(c),[detail,setDetail]=useState<StatKey|null>(null);const result=calculateBasics(levelAdjusted(d,mechanics.config).class_levels,c.race,mechanics.config);const can=(key:string)=>gm||c.editable_fields.includes(key);
 const prepared=prepareShared(d,mechanics.config,incoming),calculated=calculateDerived(prepared.character,mechanics.config),longEffects=d.hp_long_effects??[],shortEffects=d.hp_short_effects??[];const hpLong=prepared.character.hp_long_effects??[],hpShort=prepared.character.hp_short_effects??[];const hpStack=stackGroups(hpLong,hpShort);
 const defenses=calculateDefenses(stateOf(d),calculated.abilities.dexterity,prepared.extras,mechanics.config);
 const health=calculateHp(effectiveBaseHp(result.values.hp.value,prepared.character),calculated.abilities.constitution,prepared.character.class_levels.length,hpLong,hpShort);
 const sourceKeys:StatKey[]=[...abilityKeys,...derivedFields.map(([key])=>key)];
 const valid=validHpEffects(longEffects)&&validHpEffects(shortEffects)&&sourceKeys.every(key=>{const group=effectGroup(d,key);return validHpEffects(group.long)&&validHpEffects(group.short)&&(!skillOnly(key)||!group.short.length)})&&abilityKeys.every(key=>calculated.abilities[key]>=0);
 const sourceCan=(key:StatKey,side:'long'|'short')=>can(abilityKeys.includes(key as typeof abilityKeys[number])?(side==='long'?'ability_permanent':'ability_temporary'):(side==='long'?'derived_long_effects':'derived_short_effects'));
 function changeGroup(key:StatKey,group:EffectGroup){setD({...d,stat_effects:{...d.stat_effects,[key]:group}})}
 const detailName=detail?(abilityNames[detail]||derivedFields.find(([k])=>k===detail)?.[1]):'';
 const detailGroup=detail?effectGroup(d,detail):null;const displayedGroup=detail?effectGroup(prepared.character,detail):null;const detailStack=displayedGroup?stackGroups(displayedGroup.long,displayedGroup.short):null;
 return <>{gm&&<DmAdjustments incoming={{[c.id]:incoming}} character={c} config={mechanics.config} busy={busy} save={save}/>}<form className="panel quick-card" onSubmit={e=>{e.preventDefault();if(!valid)return;const patch:Partial<Character>={rule_state:stateOf(d)};if(can('ability_permanent')||can('ability_temporary')||can('derived_long_effects')||can('derived_short_effects'))patch.stat_effects=d.stat_effects??{};if(can('hp_long_effects'))patch.hp_long_effects=longEffects;if(can('hp_short_effects'))patch.hp_short_effects=shortEffects;void save(c,patch)}}><div className="quick-title"><div><h2>{c.name}</h2><small>{c.race||'种族待选'} · {classSummary(c.class_levels,classCatalog(mechanics.config))} · 总等级 {c.class_levels.length}</small></div><span className="badge">当前状态</span></div>
 <ModuleControls roster={roster} character={d} config={mechanics.config} gm={gm} state={stateOf(d)} onChange={state=>setD({...d,rule_state:state})} busy={busy}/><ReceivedEffects incoming={incoming} state={stateOf(d)} onChange={state=>setD({...d,rule_state:state})} busy={busy}/><div className="quick-abilities">{abilityFields.map(([key,label])=><article key={key}><h3>{label}<output>{calculated.abilities[key]}</output></h3><div className="quick-innate">天生 <b>{c[key]}</b></div><div className="quick-innate">调整值 <b>{signed(Math.floor((calculated.abilities[key]-10)/2))}</b></div><button type="button" className="quick-source" onClick={()=>setDetail(detail===key?null:key)}>长效／短效明细</button></article>)}</div>
 <details className="hp-summary"><summary><span>生命值 HP</span><strong>{health.total??'待配置'}</strong><small>展开明细</small></summary><div className="hp-contributions"><div className="hp-line"><span>职业贡献</span><b>{health.profession===null?'待配置':signed(health.profession)}</b></div>{health.profession===null&&<p className="muted">{result.values.hp.missing.join('；')}</p>}<div className="hp-line"><span>体质调整贡献</span><b>{signed(health.constitution)}</b></div><HpEffects title="HP 长效变量" effects={longEffects} total={health.long} generated={hpLong.filter(e=>e.origin)} report={hpStack.rows} editable={can('hp_long_effects')} busy={busy} onChange={effects=>setD({...d,hp_long_effects:effects})}/><HpEffects title="HP 短效变量" effects={shortEffects} total={health.short} generated={hpShort.filter(e=>e.origin)} report={hpStack.rows} editable={can('hp_short_effects')} busy={busy} onChange={effects=>setD({...d,hp_short_effects:effects})}/></div></details>
 {gm&&<details><summary>武器伤害体型调整（GM）</summary>{([['body','体型变化（档）'],['weapon','武器等效体型变化（档）']] as const).map(([key,label])=><label key={key}>{label}<input type="number" step={1} value={stateOf(d).sizeAdjustments?.[key]??0} disabled={busy} onChange={e=>setD({...d,rule_state:{...stateOf(d),sizeAdjustments:{body:0,weapon:0,...stateOf(d).sizeAdjustments,[key]:Number(e.target.value)}}})}/></label>)}<small className="muted">仅调整武器伤害档位，能力提供的变化会另外合计。修改后保存操作。</small></details>}
 <WeaponDamagePanel state={stateOf(d)} catalog={ruleCatalog(mechanics.config)} raceSize={result.race?.size} extras={prepared.extras} character={prepared.character} config={mechanics.config} effects={prepared.effects}/><div className="quick-results"><article><small>攻击次数</small><strong>{calculateAttackCount(c.class_levels,mechanics.config,prepared.extras.attackCount?.long,prepared.extras.attackCount?.short)??'待配置'}</strong></article>{([['defense','防御'],['touchDefense','接触防御'],['flatDefense','措手不及防御']] as const).map(([key,label])=><article key={key}><small>{label}</small><strong>{defenses[key].total}</strong>{defenses[key].scenarios.map(s=><small key={s.id}>{s.label}：{s.total}</small>)}<details><summary>防御来源</summary><p>基础10，敏捷贡献 {signed(defenses[key].dex)}</p>{defenses[key].stack.rows.filter(row=>row.effect.value!==0).map((row,i)=><p key={i}>{row.effect.name} {signed(row.effect.value)} · {row.reason}</p>)}</details></article>)}{derivedFields.map(([key,label])=><article key={key}><small>{label}</small><strong>{calculated.values[key].total??'待配置'}</strong>{calculated.values[key].scenarios.map(s=><small key={s.context}>{s.context}：{s.total??'待配置'}</small>)}<button className="quick-source" type="button" onClick={()=>setDetail(detail===key?null:key)}>查看明细</button></article>)}{[['grapple','擒抱对抗'],['initiative','先攻'],['damageReduction','伤害减免'],['spellResistance','法术抗性']].map(([key,label])=>{const group=prepared.extras[key as keyof typeof prepared.extras];return <article key={key}><small>{label}</small>{key==='grapple'?<strong className="pending-value">基础待配置</strong>:<strong>{Math.floor(stackGroups(group?.long,group?.short).total)+(key==='initiative'?Math.floor((calculated.abilities.dexterity-10)/2):0)}</strong>}{group&&<small>模块附加 {signed(stackGroups(group.long,group.short).total)}</small>}</article>})}{energyResistances.map(([key,label])=>{const group=prepared.extras[key],value=Math.floor(stackGroups(group?.long,group?.short).total);return value===0?null:<article key={key}><small>{label}抗性</small><strong>{value}</strong></article>})}{prepared.extras.rangedDamageReduction&&<article><small>对远程武器伤害减免</small><strong>{Math.floor(stackGroups(prepared.extras.rangedDamageReduction.long,prepared.extras.rangedDamageReduction.short).total)}</strong></article>}{prepared.extras.spellDamageReduction&&<article><small>对法术伤害减免</small><strong>{Math.floor(stackGroups(prepared.extras.spellDamageReduction.long,prepared.extras.spellDamageReduction.short).total)}</strong></article>}<article><small>通用伤害附加（力量见武器）</small><strong>{Math.floor(stackGroups(prepared.extras.damage?.long,prepared.extras.damage?.short).total)}</strong><details><summary>模块来源</summary>{stackGroups(prepared.extras.damage?.long,prepared.extras.damage?.short).rows.map((row,i)=><p key={i}>{row.effect.name} {signed(row.effect.value)} · {row.reason}</p>)}</details></article><article><small>移动速度</small><strong>{movementDisplay(c.id,stateOf(d),roster,armorSpeed(stateOf(d),result.race?.speed,mechanics.config,prepared.extras),result.race?.unit??'尺',mechanics.config)}</strong>{prepared.extras.speed&&<small>模块附加 {signed(stackGroups(prepared.extras.speed.long,prepared.extras.speed.short).total)}（在状态倍率之后加入）</small>}</article><article><small>体型</small><strong>{result.race?.size||'待配置'}</strong></article><article><small>本职主属性</small>{result.primary.map(p=><p key={p.name}>{p.name}：{abilityNames[p.ability]||'待配置'}</p>)}</article></div>
 {detail&&detailGroup&&<section className="quick-detail"><div className="section-title"><h3>{detailName} · 来源明细</h3><button className="secondary" type="button" onClick={()=>setDetail(null)}>收起</button></div>{derivedFields.some(([key])=>key===detail)&&<>{calculated.values[detail as typeof derivedFields[number][0]].missing.map((text,i)=><p className="muted" key={i}>{text}</p>)}{calculated.values[detail as typeof derivedFields[number][0]].parts.map((part,i)=><div className="hp-line" key={i}><span>{part.label}</span><b>{signed(part.value)}</b></div>)}</>}<HpEffects title={`${detailName}长效变量`} effects={detailGroup.long} total={detailStack?.long??0} generated={displayedGroup?.long.filter(e=>e.origin)} report={detailStack?.rows} editable={sourceCan(detail,'long')} busy={busy} onChange={effects=>changeGroup(detail,{...detailGroup,long:effects})}/>{!skillOnly(detail)&&<HpEffects title={`${detailName}短效变量`} effects={detailGroup.short} total={detailStack?.short??0} generated={displayedGroup?.short.filter(e=>e.origin)} report={detailStack?.rows} editable={sourceCan(detail,'short')} busy={busy} onChange={effects=>changeGroup(detail,{...detailGroup,short:effects})}/>}</section>}
 <CasterLevelPanel c={d} config={mechanics.config} gm={gm} busy={busy} onChange={setD}/><MemoPanel notes={prepared.notes}/><TimedEffectPanel c={c} d={d} setD={setD} config={mechanics.config} gm={gm} busy={busy} save={save}/><div className="quick-save"><small className="muted">属性调整值按定义计算，各项结果均在总和最后向下取整。{!valid&&' 请检查来源名称、数值及属性合计。'}</small>{(incoming.length>0||['ability_permanent','ability_temporary','derived_long_effects','derived_short_effects','hp_long_effects','hp_short_effects'].some(can)||gm||stateOf(d).instances.some(x=>x.access!=='gm')||can('weapon_context'))&&<button disabled={busy||!valid}>保存当前状态调整</button>}</div></form></>
}
function signed(value:number){return `${value>=0?'+':''}${value}`}
function HpEffects({title,effects,total,editable,busy,onChange,generated=[],report=[]}:{title:string;effects:HpEffect[];total:number;editable:boolean;busy:boolean;onChange:(effects:HpEffect[])=>void;generated?:HpEffect[];report?:ReturnType<typeof stackGroups>['rows']}){
 return <details className="hp-effects"><summary><span>{title}</span><b>{signed(total)}</b><small>查看明细</small></summary><div>{!effects.length&&!generated.length&&<p className="muted">暂无来源，合计为 0。</p>}{effects.map((effect,i)=><div className="hp-effect-row" key={effect.id}><label className="hp-effect-toggle"><input aria-label={`${title}第${i+1}项生效`} type="checkbox" disabled={!editable||busy} checked={effect.enabled} onChange={e=>onChange(effects.map((x,j)=>j===i?{...x,enabled:e.target.checked}:x))}/>生效</label><input aria-label={`${title}第${i+1}项来源`} placeholder="专长、能力或法术名称" maxLength={100} required disabled={!editable||busy} value={effect.name} onChange={e=>onChange(effects.map((x,j)=>j===i?{...x,name:e.target.value}:x))}/><input aria-label={`${title}第${i+1}项数值`} type="number" step="any" required disabled={!editable||busy} value={effect.value} onChange={e=>onChange(effects.map((x,j)=>j===i?{...x,value:Number(e.target.value)}:x))}/><select aria-label={`${title}第${i+1}项加值类型`} disabled={!editable||busy} value={effect.bonusType??'unnamed'} onChange={e=>onChange(effects.map((x,j)=>j===i?{...x,bonusType:e.target.value}:x))}>{bonusTypes.map(([key,zh,en])=><option key={key} value={key}>{zh} / {en}</option>)}</select><small className="stack-reason">{report.find(row=>row.effect.id===effect.id)?.reason}</small>{editable&&<button type="button" className="secondary" disabled={busy} onClick={()=>onChange(effects.filter((_,j)=>j!==i))}>移除</button>}</div>)}{generated.map(effect=><p className="module-source" key={effect.id}>{effect.name}：{signed(effect.value)} · {bonusTypes.find(([key])=>key===effect.bonusType)?.[1]||effect.bonusType} · {report.find(row=>row.effect.id===effect.id)?.reason||'模块来源'}</p>)}{editable&&<button type="button" className="secondary" disabled={busy} onClick={()=>onChange([...effects,{id:crypto.randomUUID(),name:'新来源',value:0,enabled:true,bonusType:'unnamed'}])}>＋ 添加{title}来源</button>}</div></details>
}
createRoot(document.getElementById('root')!).render(<App/>);
